This Terraform configuration creates an AWS CodeBuild project with:

- An example IAM role for CodeBuild
- CloudWatch Logs permissions
- S3 permissions for primary and secondary build artifacts
- One primary S3 artifact bucket
- Two secondary S3 artifact buckets
- A `NO_SOURCE` CodeBuild project with an inline buildspec that produces primary and secondary artifacts

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name of the AWS CodeBuild project."
  type        = string
  default     = "example-codebuild-secondary-artifacts"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "primary_artifacts" {
  bucket        = "${var.project_name}-primary-${random_id.suffix.hex}"
  force_destroy = true
}

